"""Request handling for the API."""


def _validate_request(data, client_id):
    """Validate the parts of a request required by the handler.

    Payload contents are validated by ``process`` because their shape depends on
    the operation being requested.  This function only checks the invariants
    shared by every request.
    """
    if data is None:
        raise ValueError("request data is required")

    if not isinstance(client_id, str):
        raise TypeError("client_id must be a string")

    if not client_id.strip():
        raise ValueError("client_id must not be empty")


def handle_request(data, client_id):
    """Validate, rate-limit, and process an incoming API request."""
    _validate_request(data, client_id)

    if not check_rate_limit(client_id):
        raise RuntimeError("rate limit exceeded")

    return process(data)

